import{z as n,x as s,o as d,c as i,q as o,j as r,D as a,d as c,s as l,S as p}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Pratt 算符优先","description":"","frontmatter":{"title":"Pratt 算符优先","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pratt-parsing.md","filePath":"cs/pratt-parsing.md","lastUpdated":1791413859000}'),E={name:"cs/pratt-parsing.md"};function B(P,e,b,A,u,_){const t=s("Mermaid");return d(),i("div",null,[e[2]||(e[2]=o('<h1 id="pratt-算符优先" tabindex="-1">Pratt 算符优先 <a class="header-anchor" href="#pratt-算符优先" aria-label="Permalink to &quot;Pratt 算符优先&quot;">​</a></h1><div class="epigraph"><p>每个记号一个左约束力与一个 nud/led 函数；解析表达式不必为每一优先级写一层非终结符。</p><footer>—— 据 Pratt, Top Down Operator Precedence, 1973；对照龙书的算符优先与表达式文法整理</footer></div><p>上一课<a href="/cs/peg-packrat">PEG</a>用有序选择能写表达式，但左结合与多层优先级会把规则写成楼梯，左递归还要改。主干 CFG 用分层 <code>E → E + T | T</code>。缺口是<strong>Pratt</strong>：一张算符表，递归下降只留一个 <code>parseExpression(rbp)</code>。本课钉 nud/led 与绑定力，不把整门语言都改成 Pratt。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LL 分层文法正确但冗长；PEG 长枝优先要小心。Pratt：前缀记号提供 <code>nud</code>（null denotation），中缀/后缀提供 <code>led</code>（left denotation）。当前约束力 <code>lbp</code> 大于调用者的 <code>rbp</code> 则继续吃中缀。<span class="marginnote">「绑定力」翻译成大白话就是优先级的数字外衣：<code>lbp</code>（左约束力）是「我这个算符想抢右边操作数有多急」，<code>rbp</code>（右约束力）是「调用我时允许你最多吃到哪一层」。每读到一个中缀算符就问一句：你的 <code>lbp</code> 比我给你的 <code>rbp</code> 大吗？大就归你继续吃，不大就把左边的东西还给上一层。</span>缺口是这份<strong>按记号分派的表达式分析</strong>，不是再算 FIRST。</p><p>数字、标识符、<code>(</code> 走 nud；<code>+</code> <code>*</code> <code>.</code> <code>(</code>（调用）走 led。一元 <code>-</code> 与二元 <code>-</code> 用同一 lexeme、不同 nud/led。</p><h3 id="绑定力不是-lalr-的-left" tabindex="-1">绑定力不是 LALR 的 <code>%left</code> <a class="header-anchor" href="#绑定力不是-lalr-的-left" aria-label="Permalink to &quot;绑定力不是 LALR 的 `%left`&quot;">​</a></h3><p><code>%left</code> 改的是冲突格；Pratt 的数字是手写下降的循环条件。二者可对齐同一张优先级表，算法不是同一份自动机。</p><p><span class="marginnote">Pratt 1973（POPL）。Vaughan Pratt 的「自上而下算符优先」被后来的 JS 引擎与教材反复实现。龙书另有算符优先分析（自底向上），名称相近、栈不同，本课不混。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>parse(rbp)</code>：读一个记号，调 <code>nud</code> 得左值；当下一记号 <code>lbp &gt; rbp</code> 则调其 <code>led(左值)</code>。右结合：<code>led</code> 里用 <code>lbp-1</code> 递归。调用与下标是 led，左值已是 callee 或数组。</p>',11)),(d(),r(p,null,{default:a(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOK%5B%22%E8%AE%B0%E5%8F%B7%22%5D%20--%3E%20NUD%5B%22nud%20%E5%89%8D%E7%BC%80%22%5D%0A%20%20NUD%20--%3E%20LOOP%5B%22lbp%20%3E%20rbp%3F%22%5D%0A%20%20LOOP%20--%3E%20LED%5B%22led%20%E4%B8%AD%E7%BC%80%22%5D%0A%20%20LED%20--%3E%20LOOP%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<p><span class="marginnote">常见误区：初学者容易以为同一符号只能有一种身份。<code>-</code> 出现在表达式开头是一元负号（走 <code>nud</code>），夹在两个表达式之间是减法（走 <code>led</code>）——同一个 lexeme 在表里登记的是两个不同函数，按「当时左边有没有一个已解析好的左值」来分派。这也是 Pratt 表天然能容纳 <code>(</code> 既是分组又是函数调用两种角色的原因。</span></p><p>与 lex 对接：词法仍负责最长匹配；Pratt 只看种别。不要在 Pratt 里解析类型声明的全部括号歧义——那是 C 的声明语法，不是表达式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>复杂度对表达式结点线性。错误：nud 表空则非法开头。与递归下降的其余语句（<code>if</code>、块）并列：语句用下降，表达式切 Pratt，是常见手写前端。</p><p>PEG 的表达式规则可生成 Pratt，或直接写循环；本课强调人可维护的一张表。二义在 Pratt 里被表消掉：不会同时返回两棵树。</p><p>把 <code>1 + 2 * 3</code> 的解析走一遍，绑定力数字如何长出树形就看明白了（设 <code>lbp(+)=10</code>、<code>lbp(*)=20</code>）：</p>',6)),(d(),r(p,null,{default:a(()=>[l(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22parse(rbp%3D0)%3A%201%20%E8%B5%B0%20nud%EF%BC%8C%E5%B7%A6%E5%80%BC%3D1%22%5D%20--%3E%20B%5B%22%E7%9C%8B%E5%88%B0%20%2B%EF%BC%8Clbp%2010%20gt%200%22%5D%0A%20%20B%20--%3E%20C%5B%22led(%2B)%3A%20parse(rbp%3D10)%22%5D%0A%20%20C%20--%3E%20D%5B%222%20%E8%B5%B0%20nud%EF%BC%8C%E5%B7%A6%E5%80%BC%3D2%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%9C%8B%E5%88%B0%20*%EF%BC%8Clbp%2020%20gt%2010%22%5D%0A%20%20E%20--%3E%20F%5B%22led(*)%3A%20parse(rbp%3D20)%22%5D%0A%20%20F%20--%3E%20G%5B%223%20%E8%B5%B0%20nud%22%5D%0A%20%20G%20--%3E%20H%5B%22%E7%BB%93%E6%9D%9F%E7%AC%A6%20lbp%200%20%E4%B8%8D%20gt%2020%EF%BC%8C%E8%BF%94%E5%9B%9E%203%22%5D%0A%20%20H%20--%3E%20I%5B%222*3%20%E6%88%90%E4%B8%BA%20%2B%20%E7%9A%84%E5%8F%B3%E5%AD%A9%E5%AD%90%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[c(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p><span class="marginnote">右结合的诀窍在这一例里也看得见：赋值 <code>a = b = c</code> 若按左结合会类型错误，所以 <code>led</code> 里递归时把 <code>rbp</code> 设成 <code>lbp - 1</code>——故意允许同层算符「再吃一口」，于是 <code>=</code> 右边先抱成 <code>b = c</code>，整体再归 <code>a</code>。左结合运算符则用 <code>lbp - 0</code>，同级就被外层截住，<code>1-2-3</code> 因此正确地结成 <code>(1-2)-3</code>。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理增量，不把声明符（C <code>int (*p)()</code>）硬塞进 Pratt。后课默认：表达式可用算符表下降；语句级错误恢复下一课。下一课：分析失败之后如何跳过、同步。</p><p>龙书的算符优先（Floyd）是另一算法，点名对照即可，不在本课实现。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Pratt：nud/led + 左右约束力，一张表吃表达式。</li><li>右结合用略小的 rbp 递归。</li><li>与 CFG 分层、PEG 楼梯、LALR <code>%left</code> 对齐的是优先级数字，不是同一自动机。</li><li>出处：Pratt, 1973；对照 Aho et al. 算符优先章。</li></ul>',6))])}const m=n(E,[["render",B]]);export{D as __pageData,m as default};
